import { NsisUpdater } from 'electron-updater';
import { CancellationToken } from 'builder-util-runtime';
import type { UpdateEngine } from './updates';
import type { UpdateProgress } from '../shared/types';

/** Standard NSIS updater: reads the packaged app-update.yml generated by builder. */
export function createUpdateEngine(onInstallError: (error: Error) => void, updater = new NsisUpdater()): UpdateEngine {
  updater.autoDownload = false;
  updater.autoInstallOnAppQuit = false;
  updater.allowPrerelease = false;
  updater.allowDowngrade = false;
  updater.disableWebInstaller = true;
  let report: ((progress: UpdateProgress) => void) | undefined;
  updater.on('download-progress', progress => report?.(progress));
  // Rejected checks/downloads are handled by UpdateService. Install errors are emitted.
  updater.on('error', onInstallError);
  return {
    async check() {
      const result = await updater.checkForUpdates();
      if (!result) throw new Error('Updater is inactive');
      if (!result.isUpdateAvailable) return null;
      const info = result.updateInfo;
      const notes = typeof info.releaseNotes === 'string' ? info.releaseNotes : info.releaseNotes?.map(note => `${note.version}\n${note.note || ''}`).join('\n\n');
      return { version: info.version, notes: notes?.slice(0, 16000), date: info.releaseDate };
    },
    async download(signal, progress) {
      const token = new CancellationToken();
      const abort = () => token.cancel();
      signal.addEventListener('abort', abort, { once: true });
      if (signal.aborted) abort();
      report = progress;
      try { await updater.downloadUpdate(token); }
      finally { signal.removeEventListener('abort', abort); report = undefined; }
    },
    install() { updater.quitAndInstall(false, true); },
  };
}
